const url = 'http://10.0.0.164:8945/';
const timeoutMs = 20000;
const state = $getWorkflowStaticData('global');
let healthy = false;
let detail = '';

// 3 forsøk med 10 s mellomrom: én treg forespørsel (Pinchflat laster ned) er ikke nedetid (2026-11-19).
for (let attempt = 1; attempt <= 3 && !healthy; attempt++) {
  try {
    // fetch() finnes ikke i n8n-sandkassen; bruker n8n sin HTTP-hjelper.
    const response = await this.helpers.httpRequest({ url, method: 'GET', timeout: timeoutMs, returnFullResponse: true, ignoreHttpStatusErrors: true });
    healthy = response.statusCode >= 200 && response.statusCode < 400;
    detail = `HTTP ${response.statusCode}`;
  } catch (error) {
    detail = (error && (error.message || error.code || error.description)) || JSON.stringify(error);
  }
  if (!healthy && attempt < 3) await new Promise(r => setTimeout(r, 10000));
}

const previous = state.status || 'unknown';
state.status = healthy ? 'up' : 'down';
state.last_checked_at = new Date().toISOString();

// Notify only on transitions. This prevents a persistent outage from creating
// a new event every five minutes; the shared alert workflow handles delivery.
if (healthy && previous !== 'down') return [];
if (!healthy && previous === 'down') return [];

const recovered = healthy;
return [{
  json: {
    title: recovered ? 'Pinchflat er tilbake' : 'Pinchflat er utilgjengelig',
    message: recovered
      ? `Pinchflat svarte igjen (${detail}) – ${url}`
      : `Pinchflat svarte ikke normalt (${detail}) – ${url}`,
    severity: recovered ? 'info' : 'warning',
    service: 'pinchflat',
    status: recovered ? 'recovered' : 'down',
    url,
    observed_at: state.last_checked_at
  }
}];
